// ─────────────────────────────────────────────────────────────────────────────
// Timing
// ─────────────────────────────────────────────────────────────────────────────

/** Beat lengths, ms. Presentation cadence — no game balance lives here. */
const BEATS: number[] = [640, 940, 1180, 980, 860, 1280, 900, 960, 420];

/** Count-up durations, ms. */
const TALLY_MS = 1150;
const TALLY_FAST_MS = 780;

const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

function reducedMotion(): boolean {
  if (document.body.classList.contains('reduce-motion')) return true;
  try {
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch {
    return false;
  }
}

/**
 * Staged beats with a single skip switch, in the idiom of
 * `ui/battle/cinematics.ts`: every timer is tracked, every pending wait can be
 * resolved at once, and nothing survives `dispose()`.
 */
class Sequencer {
  private timers = new Set<number>();
  private waiters = new Set<() => void>();
  private tallies = new Set<() => void>();
  private settled = false;
  private dead = false;

  /** True once the sequence has been skipped, finished or disposed. */
  get finished(): boolean {
    return this.settled || this.dead;
  }

  wait(ms: number): Promise<void> {
    return new Promise<void>((resolve) => {
      if (this.finished) {
        resolve();
        return;
      }
      const fire = (): void => {
        this.waiters.delete(fire);
        resolve();
      };
      this.waiters.add(fire);
      const handle = window.setTimeout(() => {
        this.timers.delete(handle);
        fire();
      }, Math.max(0, ms));
      this.timers.add(handle);
    });
  }

  /** Tween 0 → `to` into `node`. Snaps to the final value once skipped. */
  tally(node: HTMLElement, to: number, ms: number, fmt: (n: number) => string): void {
    const paint = (v: number): void => {
      node.textContent = fmt(v);
    };
    if (this.finished || ms <= 0) {
      paint(to);
      return;
    }

    let raf = 0;
    const snap = (): void => {
      cancelAnimationFrame(raf);
      this.tallies.delete(snap);
      paint(to);
    };
    const start = performance.now();
    const step = (t: number): void => {
      const p = Math.min(1, (t - start) / ms);
      // easeOutCubic — fast off the line, a long settle onto the real number.
      paint(to * (1 - Math.pow(1 - p, 3)));
      if (p < 1) {
        raf = requestAnimationFrame(step);
        return;
      }
      this.tallies.delete(snap);
      paint(to);
    };

    paint(0);
    raf = requestAnimationFrame(step);
    this.tallies.add(snap);
  }

  /** Resolve everything immediately and land every number on its final value. */
  finish(): void {
    if (this.settled) return;
    this.settled = true;
    for (const handle of this.timers) window.clearTimeout(handle);
    this.timers.clear();
    for (const snap of Array.from(this.tallies)) snap();
    this.tallies.clear();
    for (const waiter of Array.from(this.waiters)) waiter();
    this.waiters.clear();
  }

  dispose(): void {
    this.dead = true;
    this.finish();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Framing — each win condition deserves its own voice (GDD §11)
// ─────────────────────────────────────────────────────────────────────────────

interface ReasonCopy {
  /** Struck-seal word. */
  seal: string;
  /** The headline verdict over the winner's name. */
  verdict: string;
  /** One paragraph of what actually happened. */
  lede: (winner: string, tag: string) => string;
  /** Tone for the frame: annihilation runs hot, a decision runs cold. */
  tone: 'domination' | 'forfeit' | 'timeout';
  accent: string;
}

const REASON: Record<SeasonEndReason, ReasonCopy> = {
  domination: {
    seal: 'ANNIHILATION',
    verdict: 'THE MAP IS THEIRS',
    lede: (winner, tag) =>
      `Every rival banner was driven to zero tiles while the clock was still running. ` +
      `${winner} did not win on points — [${tag}] took the ground and left nobody standing on any of it.`,
    tone: 'domination',
    accent: 'var(--ember)',
  },
  forfeit: {
    seal: 'WALKOVER',
    verdict: 'LAST CHARTER STANDING',
    lede: (winner, tag) =>
      `Every other charter dissolved before the bell. There was no final battle to fight — ` +
      `[${tag}] simply outlasted the war, and ${winner} inherits a map nobody else was left to contest.`,
    tone: 'forfeit',
    accent: 'var(--violet)',
  },
  timeout: {
    seal: 'DECISION',
    verdict: 'THE BELL DECIDES',
    lede: (winner, tag) =>
      `The season clock ran out with the map still contested, so it was settled the way it was always ` +
      `going to be settled: on held ground. ${winner} [${tag}] finished the season holding the most tiles.`,
    tone: 'timeout',
    accent: 'var(--gold)',
  },
};

/** Which rung of the tiebreaker chain actually separated first from second. */
type Decider = 'tiles' | 'power' | 'harvest' | 'charter';

const DECIDER_LABEL: Record<Decider, string> = {
  tiles: 'MOST TILES HELD',
  power: 'TOTAL POWER POINTS',
  harvest: 'TOTAL RESOURCES HARVESTED',
  charter: 'CHARTER REGISTRATION ORDER',
};

function deciderOf(top: GuildStanding | undefined, next: GuildStanding | undefined): Decider {
  if (!top || !next) return 'tiles';
  if (top.tiles !== next.tiles) return 'tiles';
  if (top.power !== next.power) return 'power';
  const a = top.harvested.m + top.harvested.g;
  const b = next.harvested.m + next.harvested.g;
  if (a !== b) return 'harvest';
  return 'charter';
}

// ─────────────────────────────────────────────────────────────────────────────
// Heraldry
// ─────────────────────────────────────────────────────────────────────────────

/**
 * A laurel wreath drawn as two mirrored tangential leaf arcs. Deterministic and
 * self-contained; `currentColor` lets the frame tint it from `guild.color`.
 */
function laurelMarkup(): string {
  const leaves: string[] = [];
  const N = 10;

  for (let i = 0; i < N; i++) {
    const t = i / (N - 1);
    const deg = 82 - t * 142; // bottom-right sweeping up past the shoulder
    const rad = (deg * Math.PI) / 180;
    const radius = 94 - t * 5;
    const x = 120 + Math.cos(rad) * radius;
    const y = 120 + Math.sin(rad) * radius;
    const rx = 15 - t * 4.5;
    const ry = 6.4 - t * 1.6;
    const spin = deg + 104;
    const alpha = (0.42 + t * 0.5).toFixed(2);

    leaves.push(
      `<ellipse cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" rx="${rx.toFixed(1)}" ry="${ry.toFixed(
        1,
      )}" transform="rotate(${spin.toFixed(1)} ${x.toFixed(1)} ${y.toFixed(
        1,
      )})" opacity="${alpha}"/>`,
    );
    leaves.push(
      `<ellipse cx="${(240 - x).toFixed(1)}" cy="${y.toFixed(1)}" rx="${rx.toFixed(
        1,
      )}" ry="${ry.toFixed(1)}" transform="rotate(${(180 - spin).toFixed(1)} ${(240 - x).toFixed(
        1,
      )} ${y.toFixed(1)})" opacity="${alpha}"/>`,
    );
  }

  return `<svg viewBox="0 0 240 240" aria-hidden="true" class="fin-laurel__svg">
      <g fill="currentColor">${leaves.join('')}</g>
      <g fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" opacity=".55">
        <path d="M133 213A96 96 0 0 0 212 92"/>
        <path d="M107 213A96 96 0 0 1 28 92"/>
      </g>
      <g fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" opacity=".8">
        <path d="M107 213l13 12 13-12"/>
        <path d="M120 225v9"/>
      </g>
    </svg>`;
}

/** Hue-tinted monogram for a commander. Local to this screen by design. */
function commanderTile(name: string, hue: number, bot: boolean): HTMLElement {
  const parts = name.trim().split(/[\s.-]+/).filter(Boolean);
  const initials =
    parts.length === 0
      ? '??'
      : parts.length === 1
        ? parts[0].slice(0, 2).toUpperCase()
        : (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();

  const tint = `hsl(${Math.round(hue)}, 82%, 64%)`;
  const wrap = el('span', {
    class: bot ? 'fin-tile is-bot' : 'fin-tile',
    style: `--mark:${tint}`,
    aria: { label: name },
  });
  wrap.appendChild(
    svgEl(
      `<svg viewBox="0 0 64 64" aria-hidden="true">
         <path d="M32 4l24.2 14v28L32 60 7.8 46V18z" fill="${tint}" fill-opacity=".14"
               stroke="${tint}" stroke-width="3" stroke-linejoin="round"/>
       </svg>`,
    ),
  );
  wrap.appendChild(el('b', { text: initials }));
  return wrap;
}

// ─────────────────────────────────────────────────────────────────────────────
// Derived records — every one of these reads only from GameState
// ─────────────────────────────────────────────────────────────────────────────

interface Holder {
  playerId: PlayerId;
  name: string;
  hue: number;
  bot: boolean;
  tag: string;
  color: number;
  value: number;
}

interface Award {
  key: string;
  title: string;
  /** The criterion, stated so nobody has to guess how it was measured. */
  criterion: string;
  holder?: Holder;
  value: number;
  unit: string;
  note: string;
  tone: 'gold' | 'cyan' | 'teal' | 'violet' | 'shame';
  /** Rendered instead of a holder when the data genuinely is not there. */
  blank?: string;
}

function holderOf(state: GameState, playerId: PlayerId, value: number): Holder | undefined {
  const player = state.players[playerId];
  if (!player) return undefined;
  const guild = player.guildId ? state.guilds[player.guildId] : undefined;
  return {
    playerId,
    name: player.name,
    hue: player.hue,
    bot: player.bot,
    tag: guild?.tag ?? '—',
    color: guild?.color ?? 0x64789a,
    value,
  };
}

/** Highest scoring commander for a metric, ties broken by name for stability. */
function best(
  state: GameState,
  score: (playerId: PlayerId) => number,
): { playerId: PlayerId; value: number } | undefined {
  let bestId: PlayerId | undefined;
  let bestValue = 0;
  for (const player of Object.values(state.players)) {
    const value = score(player.id);
    if (value <= 0) continue;
    if (bestValue > value) continue;
    if (bestValue === value && bestId) {
      const incumbent = state.players[bestId]?.name ?? '';
      if (incumbent.localeCompare(player.name) <= 0) continue;
    }
    bestId = player.id;
    bestValue = value;
  }
  return bestId ? { playerId: bestId, value: bestValue } : undefined;
}

/**
 * GDD §7.2 / §14 — the 0-0-0 roll is broadcast into the roller's own guild
 * channel as a system message, on purpose, so everyone knows. That broadcast is
 * the only record of it in `GameState`, so this reads it back out of the log.
 *
 * The channel is a rolling window of `GUILD.chatHistory` messages, which the
 * award copy says out loud rather than pretending to a full-season count.
 */
function tripleZeroTally(state: GameState, guildId: GuildId): Map<PlayerId, number> {
  const tally = new Map<PlayerId, number>();
  const guild = state.guilds[guildId];
  if (!guild) return tally;

  // Longest name first, so "REY" can never swallow a line about "REYNARD".
  const members = guild.memberIds
    .map((id) => ({ id, key: (state.players[id]?.name ?? '').toUpperCase() }))
    .filter((m) => m.key.length > 0)
    .sort((a, b) => b.key.length - a.key.length);

  for (const message of messages(state, guildChannel(guildId))) {
    if (message.kind !== 'triple_zero') continue;
    const text = message.text.toUpperCase();
    const hit = members.find((m) => text.startsWith(m.key));
    if (hit) tally.set(hit.id, (tally.get(hit.id) ?? 0) + 1);
  }
  return tally;
}

function fortTally(state: GameState): Map<PlayerId, number> {
  const tally = new Map<PlayerId, number>();
  for (const hex of Object.values(state.world.hexes)) {
    if (!hex.ownerId || hex.fortLevel <= 0) continue;
    tally.set(hex.ownerId, (tally.get(hex.ownerId) ?? 0) + hex.fortLevel);
  }
  return tally;
}

function computeAwards(
  state: GameState,
  powers: Map<PlayerId, PowerBreakdown>,
  myGuildId: GuildId | undefined,
): Award[] {
  const forts = fortTally(state);
  const powerFor = (id: PlayerId): PowerBreakdown => powers.get(id) ?? powerOf(state, id);

  const domain = best(state, (id) => powerFor(id).hexCount);
  const iron = best(state, (id) => powerFor(id).unitPower);
  const mines = best(state, (id) => mineralEquivalent(state.players[id]?.harvested ?? { m: 0, g: 0 }));
  const mason = best(state, (id) => forts.get(id) ?? 0);
  const vault = best(state, (id) => {
    const p = state.players[id];
    return p ? mineralEquivalent({ m: p.minerals, g: p.gas }) : 0;
  });

  const awards: Award[] = [];

  if (domain) {
    awards.push({
      key: 'domain',
      title: 'LARGEST DOMAIN',
      criterion: 'hexes owned at the final bell',
      holder: holderOf(state, domain.playerId, domain.value),
      value: domain.value,
      unit: 'HEXES',
      note: 'More ground than any other commander alive, and every hour of it paid out.',
      tone: 'gold',
    });
  }

  if (iron) {
    awards.push({
      key: 'iron',
      title: 'HEAVIEST IRON',
      criterion: 'highest unit power — armies plus reserve garrisons',
      holder: holderOf(state, iron.playerId, iron.value),
      value: iron.value,
      unit: 'UNIT PP',
      note: 'Power from the units they command, counted in mineral equivalents.',
      tone: 'cyan',
    });
  }

  if (mines) {
    awards.push({
      key: 'mines',
      title: 'DEEPEST MINES',
      criterion: 'most resources harvested across the whole season',
      holder: holderOf(state, mines.playerId, mines.value),
      value: mines.value,
      unit: 'M-EQ',
      note: `Banked, not merely produced — overflow above the ${fmtNum(
        ECONOMY.capMinerals,
      )} cap never counted.`,
      tone: 'teal',
    });
  }

  if (mason) {
    awards.push({
      key: 'mason',
      title: 'THE MASON',
      criterion: 'highest total fortification levels standing',
      holder: holderOf(state, mason.playerId, mason.value),
      value: mason.value,
      unit: 'FORT LV',
      note: 'Defence is a valid strategy. Somebody took that personally.',
      tone: 'violet',
    });
  }

  if (vault) {
    awards.push({
      key: 'vault',
      title: 'DIED RICH',
      criterion: 'largest stockpile still unspent when the bell rang',
      holder: holderOf(state, vault.playerId, vault.value),
      value: vault.value,
      unit: 'M-EQ IDLE',
      note: 'Saved it all for a season that ended without them. Congratulations on the balance sheet.',
      tone: 'shame',
    });
  }

  // GDD §7.2 — publicly humiliating by design.
  if (myGuildId) {
    const zeros = tripleZeroTally(state, myGuildId);
    let worstId: PlayerId | undefined;
    let worst = 0;
    for (const [id, n] of zeros) {
      if (n > worst) {
        worst = n;
        worstId = id;
      }
    }
    awards.push({
      key: 'zeros',
      title: 'WORST LUCK OF THE SEASON',
      criterion: `0-0-0 rolls broadcast to your guild channel`,
      holder: worstId ? holderOf(state, worstId, worst) : undefined,
      value: worst,
      unit: worst === 1 ? 'TOTAL FAILURE' : 'TOTAL FAILURES',
      note: `Counted from the guild log, which keeps the last ${GUILD.chatHistory} transmissions. No reroll subsystem exists.`,
      tone: 'shame',
      blank: `NO 0-0-0 ON RECORD IN THE LAST ${GUILD.chatHistory} TRANSMISSIONS. SOMEBODY GOT AWAY WITH IT.`,
    });
  }

  return awards;
}

interface CommandCounts {
  armies: number;
  inArmies: number;
  reserves: number;
}

/** Chassis the player still commands. Roster arithmetic, not power scoring. */
function commandCounts(state: GameState, playerId: PlayerId): CommandCounts {
  let armies = 0;
  let inArmies = 0;
  for (const army of Object.values(state.armies)) {
    if (army.ownerId !== playerId) continue;
    armies++;
    inArmies += army.units.length;
  }
  let reserves = 0;
  for (const hex of Object.values(state.world.hexes)) {
    if (hex.ownerId !== playerId) continue;
    for (const type of Object.keys(hex.reserves) as UnitType[]) {
      reserves += hex.reserves[type] ?? 0;
    }
  }
  return { armies, inArmies, reserves };
}

function compositionOf(army: Army): [UnitType, number][] {
  const counts = new Map<UnitType, number>();
  for (const unit of army.units) counts.set(unit.type, (counts.get(unit.type) ?? 0) + 1);
  return Array.from(counts.entries()).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
}

