// Screen
// ─────────────────────────────────────────────────────────────────────────────

export function createSeasonEndScreen(backend: IBackend): Screen {
  // ── frame ─────────────────────────────────────────────────────────────────
  const sky = el(
    'div',
    { class: 'fin__sky', aria: { hidden: 'true' } },
    el('i', { class: 'fin__bleed' }),
    el('i', { class: 'fin__rays' }),
    el('i', { class: 'fin__shafts' }),
    el('i', { class: 'fin__grid' }),
    el('i', { class: 'fin__scan' }),
    el('i', { class: 'fin__vig' }),
  );
  const flash = el('div', { class: 'fin__flash', aria: { hidden: 'true' } });
  const stage = el('div', { class: 'fin__stage scroll-y' });
  const tap = el('button', {
    class: 'fin__tap',
    attrs: { type: 'button' },
    aria: { label: 'skip the ceremony' },
  });
  const skipHint = el(
    'div',
    { class: 'fin__skiphint' },
    el('i', { class: 'fin__skipdot', aria: { hidden: 'true' } }),
    el('span', { text: 'TAP ANYWHERE TO SKIP' }),
  );
  const cue = el(
    'div',
    { class: 'fin__cue', aria: { hidden: 'true' } },
    el('span', { text: 'FULL RECORD BELOW' }),
    el('i', { html: ICONS.chevronDown }),
  );

  // `cue` is appended into the crown by `compose()` so it stays in flow.
  const root = el('div', { class: 'screen fin' }, sky, flash, stage, tap, skipHint);

  // ── lifecycle state ───────────────────────────────────────────────────────
  const disposer = new Disposer();
  const hooks = new Map<number, ((seq: Sequencer) => void)[]>();
  let seq: Sequencer | null = null;
  /** The frozen final snapshot. Captured once, never overwritten. */
  let finalState: GameState | null = null;
  let composed = false;

  const on = (beat: number, fn: (seq: Sequencer) => void): void => {
    const list = hooks.get(beat);
    if (list) list.push(fn);
    else hooks.set(beat, [fn]);
  };

  // ── small builders ────────────────────────────────────────────────────────

  const block = (
    beat: number,
    label: string,
    right: string | undefined,
    ...children: (Node | null)[]
  ): HTMLElement => {
    const head = el(
      'div',
      { class: 'fin-block__head' },
      el('span', { class: 'fin-block__label', text: label }),
      el('span', { class: 'fin-block__line', aria: { hidden: 'true' } }),
      right ? el('span', { class: 'fin-block__right', text: right }) : null,
    );
    const node = el('section', { class: `fin-block fin-block--b${beat}` }, head);
    for (const child of children) if (child) node.appendChild(child);
    return node;
  };

  const tallyNode = (
    beat: number,
    value: number,
    cls: string,
    ms: number,
    fmt: (n: number) => string = (n) => fmtNum(n),
  ): HTMLElement => {
    const node = el('b', { class: cls, text: '0' });
    on(beat, (s) => s.tally(node, value, ms, fmt));
    return node;
  };

  const cell = (
    beat: number,
    key: string,
    value: number,
    suffix: string,
    tint: string,
    fmt: (n: number) => string = (n) => fmtNum(n),
  ): HTMLElement =>
    el(
      'div',
      { class: 'fin-cell', style: `--tint:${tint}` },
      el('span', { class: 'fin-cell__k', text: key }),
      tallyNode(beat, value, 'fin-cell__v', TALLY_FAST_MS, fmt),
      el('span', { class: 'fin-cell__s', text: suffix }),
    );

  // ── composition ───────────────────────────────────────────────────────────

  function compose(state: GameState): void {
    clear(stage);
    hooks.clear();

    const season = state.season;
    const reason: SeasonEndReason = season.endReason ?? 'timeout';
    const copy = REASON[reason];
    const standings = guildStandings(state);
    const winner: Guild | undefined = season.winnerGuildId
      ? state.guilds[season.winnerGuildId]
      : undefined;
    const winnerRow = standings.find((s) => s.guildId === season.winnerGuildId);
    const me = state.players[state.meId];
    const myGuildId = me?.guildId;
    const myGuild = myGuildId ? state.guilds[myGuildId] : undefined;
    const myRank = standings.findIndex((s) => s.guildId === myGuildId);
    const iWon = Boolean(myGuildId && myGuildId === season.winnerGuildId);
    const totalTiles = standings.reduce((n, s) => n + s.tiles, 0);
    const decider = deciderOf(standings[0], standings[1]);

    // Power breakdowns, computed once by the game module and reused everywhere.
    const powers = new Map<PlayerId, PowerBreakdown>();
    for (const player of Object.values(state.players)) {
      powers.set(player.id, powerOf(state, player.id));
    }

    // The frame takes the winner's colour whether or not it is the player's.
    const band = winner ? winner.color : 0xffd15c;
    root.style.setProperty('--band', cssHex(band));
    root.style.setProperty('--band-soft', rgba(band, 0.26));
    root.style.setProperty('--band-dim', rgba(band, 0.1));
    root.style.setProperty('--band-hot', rgba(band, 0.65));
    root.style.setProperty('--seal', copy.accent);
    root.classList.toggle('is-mine', iWon);
    root.classList.toggle('is-theirs', !iWon);
    root.dataset.reason = reason;

    // ── 1–4: the crown ──────────────────────────────────────────────────────
    const weeks = Math.max(1, Math.round(SEASON.lengthMs / WEEK_MS));
    const fought = fmtDuration(Math.max(0, state.now - season.startedAt));

    const crown = el('header', { class: 'fin-crown' });

    crown.appendChild(
      el(
        'div',
        { class: 'fin-crown__eyebrow' },
        el('span', { class: 'fin-crown__season', text: season.name }),
        el('i', { class: 'fin-crown__pip', aria: { hidden: 'true' } }),
        el('span', { text: `${weeks}-WEEK CAMPAIGN` }),
        el('i', { class: 'fin-crown__pip', aria: { hidden: 'true' } }),
        el('span', { class: 'mono', text: `RAN ${fought}` }),
        el('i', { class: 'fin-crown__pip', aria: { hidden: 'true' } }),
        el('span', { class: 'mono', text: `FINAL BELL ${fmtClock(state.now)}` }),
      ),
    );

    crown.appendChild(
      el(
        'div',
        { class: 'fin-seal' },
        el('i', { class: 'fin-seal__rule', aria: { hidden: 'true' } }),
        el('span', { class: 'fin-seal__word display', text: copy.seal }),
        el('i', { class: 'fin-seal__rule', aria: { hidden: 'true' } }),
      ),
    );

    const medal = el('div', { class: 'fin-medal' });
    medal.appendChild(el('i', { class: 'fin-medal__glow', aria: { hidden: 'true' } }));
    medal.appendChild(el('i', { class: 'fin-medal__banner', aria: { hidden: 'true' } }));
    const laurel = el('div', { class: 'fin-laurel', aria: { hidden: 'true' } });
    laurel.appendChild(svgEl(laurelMarkup()));
    medal.appendChild(laurel);
    const disc = el('div', { class: 'fin-medal__disc' });
    if (winner) disc.appendChild(guildSigil(winner, 64));
    else disc.appendChild(el('span', { class: 'fin-medal__none', text: '—' }));
    medal.appendChild(disc);
    medal.appendChild(
      el('div', { class: 'fin-medal__rank display', text: winner ? 'I' : '?' }),
    );
    crown.appendChild(medal);

    crown.appendChild(
      el('div', {
        class: 'fin-crown__verdict display',
        text: winner ? copy.verdict : 'NO BANNER STANDING',
      }),
    );
    crown.appendChild(
      el('div', {
        class: 'fin-crown__name display',
        text: winner ? winner.name : 'SEASON VOID',
        attrs: { 'data-echo': winner ? winner.name : 'SEASON VOID' },
      }),
    );
    crown.appendChild(
      el(
        'div',
        { class: 'fin-crown__tagline' },
        el('span', { class: 'fin-crown__tag mono', text: winner ? `[${winner.tag}]` : '[——]' }),
        el('span', {
          class: 'fin-crown__motto',
          text: winner?.motto || 'no motto filed',
        }),
      ),
    );

    crown.appendChild(
      el('p', {
        class: 'fin-crown__lede',
        text: winner
          ? copy.lede(winner.name, winner.tag)
          : 'The clock ran out with no charter registered on the board. Nothing was decided and nothing was taken.',
      }),
    );

    // The tiebreaker chain, presented on the terms the game actually used.
    const chain = el('div', { class: 'fin-chain' });
    chain.appendChild(
      el('div', {
        class: 'fin-chain__head',
        text: reason === 'timeout' ? 'SETTLED ON' : 'STANDINGS ORDERED BY',
      }),
    );
    const rungs: Decider[] = ['tiles', 'power', 'harvest'];
    rungs.forEach((rung, i) => {
      const live = reason === 'timeout' && decider === rung;
      const spent = reason === 'timeout' && rungs.indexOf(decider) > i;
      chain.appendChild(
        el(
          'div',
          {
            class: `fin-chain__rung${live ? ' is-live' : ''}${spent ? ' is-spent' : ''}`,
          },
          el('span', { class: 'fin-chain__n mono', text: `0${i + 1}` }),
          el('span', { class: 'fin-chain__k', text: DECIDER_LABEL[rung] }),
          live
            ? el('span', { class: 'fin-chain__flag', text: 'DECIDED HERE' })
            : spent
              ? el('span', { class: 'fin-chain__flag is-tied', text: 'TIED' })
              : null,
        ),
      );
    });
    if (reason === 'timeout' && decider === 'charter') {
      chain.appendChild(
        el('div', {
          class: 'fin-chain__note',
          text: 'Every rung tied. The board broke it on charter registration order.',
        }),
      );
    } else if (reason !== 'timeout') {
      chain.appendChild(
        el('div', {
          class: 'fin-chain__note',
          text:
            reason === 'domination'
              ? 'The chain was never needed — the win landed before the clock did.'
              : 'The chain was never needed — there was nobody left to tie with.',
        }),
      );
    }
    crown.appendChild(chain);
    crown.appendChild(cue);

    stage.appendChild(crown);

    // ── 5: podium ───────────────────────────────────────────────────────────
    const top = standings.slice(0, 3);
    if (top.length > 0) {
      const podium = el('div', { class: 'fin-podium' });
      const order = [1, 0, 2];
      for (const index of order) {
        const row = top[index];
        if (!row) continue;
        const guild = state.guilds[row.guildId];
        const place = index + 1;
        const pod = el('div', {
          class: `fin-pod fin-pod--${place}${row.guildId === myGuildId ? ' is-mine' : ''}`,
          style: `--pod:${cssHex(row.color)};--pod-soft:${rgba(row.color, 0.3)}`,
        });
        const sig = el('div', { class: 'fin-pod__sig' });
        if (guild) sig.appendChild(guildSigil(guild, 32));
        pod.appendChild(sig);
        pod.appendChild(el('div', { class: 'fin-pod__tag', text: row.tag }));
        pod.appendChild(
          el(
            'div',
            { class: 'fin-pod__col' },
            el('span', { class: 'fin-pod__place display', text: String(place) }),
            el('span', { class: 'fin-pod__tiles mono tnum' }, tallyNode(5, row.tiles, 'fin-pod__n', TALLY_FAST_MS, (n) => String(Math.round(n)))),
            el('span', { class: 'fin-pod__unit', text: 'TILES' }),
          ),
        );
        podium.appendChild(pod);
      }
      stage.appendChild(
        block(
          5,
          'FINAL PODIUM',
          `${standings.length} BANNER${standings.length === 1 ? '' : 'S'}`,
          podium,
        ),
      );
    }

    // ── 6: full leaderboard ─────────────────────────────────────────────────
    const board = el('div', { class: 'fin-board' });
    if (standings.length === 0) {
      board.appendChild(
        el('div', { class: 'fin-board__none', text: 'NO CHARTERS ON THE REGISTER' }),
      );
    }
    standings.forEach((row, i) => {
      const guild = state.guilds[row.guildId];
      const share = totalTiles > 0 ? (row.tiles / totalTiles) * 100 : 0;
      const isWinner = row.guildId === season.winnerGuildId;
      const isMine = row.guildId === myGuildId;
      const wiped = row.tiles === 0;

      const classes = ['fin-row'];
      if (isWinner) classes.push('is-win');
      if (isMine) classes.push('is-mine');
      if (wiped) classes.push('is-out');

      const bar = el('div', { class: 'fin-row__bar' }, el('i', { style: 'width:0%' }));
      on(6, (s) => {
        const fill = bar.firstElementChild as HTMLElement | null;
        if (!fill) return;
        if (s.finished) {
          fill.style.width = `${share.toFixed(2)}%`;
          return;
        }
        window.requestAnimationFrame(() => {
          fill.style.width = `${share.toFixed(2)}%`;
        });
      });

      const idBlock = el(
        'div',
        { class: 'fin-row__id' },
        el(
          'div',
          { class: 'fin-row__top' },
          el('span', { class: 'fin-row__tag', text: row.tag }),
          isWinner ? el('span', { class: 'fin-row__flag is-win', text: 'CHAMPION' }) : null,
          isMine && !isWinner ? el('span', { class: 'fin-row__flag is-me', text: 'YOUR GUILD' }) : null,
          wiped ? el('span', { class: 'fin-row__flag is-out', text: 'ELIMINATED' }) : null,
        ),
        el('div', { class: 'fin-row__name', text: row.name }),
      );

      const sig = el('div', { class: 'fin-row__sig' });
      if (guild) sig.appendChild(guildSigil(guild, 26));

      const micro = el(
        'div',
        { class: 'fin-row__micro' },
        el(
          'span',
          {},
          el('i', { text: 'POWER' }),
          tallyNode(6, row.power, 'fin-row__mv', TALLY_MS),
        ),
        el(
          'span',
          {},
          el('i', { text: 'HARVEST' }),
          tallyNode(6, row.harvested.m + row.harvested.g, 'fin-row__mv', TALLY_MS),
        ),
        el(
          'span',
          {},
          el('i', { text: 'CREW' }),
          tallyNode(6, row.memberCount, 'fin-row__mv', TALLY_FAST_MS, (n) =>
            String(Math.round(n)),
          ),
        ),
      );

      board.appendChild(
        el(
          'div',
          {
            class: classes.join(' '),
            style: `--band:${cssHex(row.color)};--band-soft:${rgba(row.color, 0.24)};--delay:${Math.min(i, 9) * 66}ms`,
          },
          el('span', { class: 'fin-row__rank mono tnum', text: String(i + 1).padStart(2, '0') }),
          sig,
          idBlock,
          el(
            'div',
            { class: 'fin-row__tiles' },
            tallyNode(6, row.tiles, 'fin-row__tv', TALLY_MS, (n) => String(Math.round(n))),
            el('i', { text: 'TILES' }),
          ),
          bar,
          micro,
        ),
      );
    });

    stage.appendChild(
      block(
        6,
        'FINAL STANDINGS',
        `${fmtNum(totalTiles)} TILES HELD`,
        board,
        el('div', {
          class: 'fin-note',
          text:
            'Ordered exactly as the season was evaluated: most tiles, then total Power Points, then total resources harvested. ' +
            `Power Points are unit worth plus hourly territory yield × ${GUILD.powerYieldK}. ` +
            'The figures above are the season scorer’s own aggregates — the same numbers that broke the tie, not a recount.',
        }),
      ),
    );

    // ── 7: the player's own record ──────────────────────────────────────────
    const dossier = el('div', { class: 'fin-dossier' });

    if (!me) {
      dossier.appendChild(
        el('div', { class: 'fin-board__none', text: 'NO COMMANDER RECORD ON FILE' }),
      );
    } else {
      const mine = powers.get(me.id) ?? powerOf(state, me.id);
      const counts = commandCounts(state, me.id);
      const roster: RosterRow[] = myGuildId ? rosterOf(state, myGuildId) : [];
      const seat = roster.findIndex((r) => r.playerId === me.id);
      const career = careerRecord();

      dossier.appendChild(
        el(
          'div',
          { class: 'fin-who' },
          commanderTile(me.name, me.hue, me.bot),
          el(
            'div',
            { class: 'fin-who__id' },
            el('div', { class: 'fin-who__name display', text: me.name }),
            el(
              'div',
              { class: 'fin-who__sub mono' },
              myGuild ? `[${myGuild.tag}] ${myGuild.name}` : 'UNAFFILIATED — NO BANNER ON FILE',
            ),
          ),
          el(
            'div',
            { class: 'fin-who__seat' },
            el('span', {
              class: 'fin-who__seatv display',
              text: seat >= 0 ? `#${seat + 1}` : '—',
            }),
            el('span', {
              class: 'fin-who__seatk',
              text: seat >= 0 ? `OF ${roster.length} IN GUILD` : 'NO GUILD SEAT',
            }),
          ),
        ),
      );

      const grid = el('div', { class: 'fin-grid' });
      grid.appendChild(
        cell(7, 'HEXES HELD', mine.hexCount, 'AT THE FINAL BELL', 'rgba(77,227,255,.26)', (n) =>
          String(Math.round(n)),
        ),
      );
      grid.appendChild(
        cell(7, 'ARMIES', counts.armies, `${counts.inArmies} CHASSIS EMBARKED`, 'rgba(157,123,255,.26)', (n) =>
          String(Math.round(n)),
        ),
      );
      grid.appendChild(
        cell(7, 'MINERALS HARVESTED', me.harvested.m, 'BANKED THIS SEASON', 'rgba(255,209,92,.26)'),
      );
      grid.appendChild(
        cell(7, 'GAS HARVESTED', me.harvested.g, 'BANKED THIS SEASON', 'rgba(61,255,207,.26)'),
      );
      grid.appendChild(
        cell(7, 'RESERVE GARRISON', counts.reserves, 'UNITS HELD OFF THE LINE', 'rgba(255,122,61,.26)', (n) =>
          String(Math.round(n)),
        ),
      );
      grid.appendChild(
        cell(
          7,
          'STILL BANKED',
          mineralEquivalent({ m: me.minerals, g: me.gas }),
          'MINERAL-EQUIVALENT, UNSPENT',
          'rgba(255,77,94,.24)',
        ),
      );
      dossier.appendChild(grid);

      // GDD §9.2 — the two halves of power never collapse into one number.
      const split = el('div', { class: 'fin-split' });
      split.appendChild(powerBar(mine.unitPower, mine.territoryPower));
      split.appendChild(
        statRow('POWER FROM THE UNITS THEY COMMAND', fmtNum(mine.unitPower), {
          accent: 'var(--cyan)',
        }),
      );
      split.appendChild(
        statRow('POWER FROM THE GROUND THEY HOLD', fmtNum(mine.territoryPower), {
          accent: 'var(--gold)',
        }),
      );
      split.appendChild(
        statRow(
          'FINAL YIELD PER HOUR',
          `${fmtNum(mine.yieldPerHour.m)} M · ${fmtNum(mine.yieldPerHour.g)} G`,
        ),
      );
      if (career.since > 0 && career.samples > 1) {
        split.appendChild(
          statRow(
            `OBSERVED PEAK SINCE ${fmtClock(career.since)}`,
            `${fmtNum(career.peakPower)} PP · ${career.peakHexes} HEXES`,
            { accent: 'var(--violet)' },
          ),
        );
      }
      dossier.appendChild(split);

      // Armies at the final bell.
      const myArmies = Object.values(state.armies)
        .filter((a) => a.ownerId === me.id)
        .sort((a, b) => b.units.length - a.units.length || a.name.localeCompare(b.name));

      dossier.appendChild(sectionHeader('ARMIES AT THE FINAL BELL'));
      if (myArmies.length === 0) {
        dossier.appendChild(
          el('div', {
            class: 'fin-armies__none',
            text: 'NO ARMY IN THE FIELD. THE SEASON ENDED WITHOUT YOU ON THE BOARD.',
          }),
        );
      } else {
        const list = el('div', { class: 'fin-armies' });
        for (const army of myArmies) {
          const chips = el('div', { class: 'fin-army__chips' });
          for (const [type, n] of compositionOf(army)) {
            const chip = el('span', {
              class: 'fin-army__chip',
              style: `--accent:${unitAccent(type)}`,
              attrs: { title: UNITS[type].codename },
            });
            chip.appendChild(svgEl(unitSilhouette(type)));
            chip.appendChild(el('b', { class: 'mono tnum', text: `×${n}` }));
            chips.appendChild(chip);
          }
          const posture = army.siege
            ? 'BESIEGING'
            : army.path.length > 0
              ? 'IN TRANSIT'
              : 'HOLDING';
          list.appendChild(
            el(
              'div',
              { class: `fin-army is-${posture.toLowerCase().replace(/\s+/g, '-')}` },
              el(
                'div',
                { class: 'fin-army__head' },
                el('span', { class: 'fin-army__name display', text: army.name }),
                el('span', { class: 'fin-army__where mono', text: army.hexId }),
                el('span', { class: 'fin-army__state', text: posture }),
              ),
              chips,
            ),
          );
        }
        dossier.appendChild(list);
      }
    }

    stage.appendChild(
      block(7, 'YOUR SEASON', me ? `COMMANDER ${me.name.toUpperCase()}` : undefined, dossier),
    );

    // ── 8: awards ───────────────────────────────────────────────────────────
    const awards = computeAwards(state, powers, myGuildId);
    const awardWrap = el('div', { class: 'fin-awards' });
    awards.forEach((award, i) => {
      const node = el('article', {
        class: `fin-award fin-award--${award.tone}`,
        style: `--delay:${Math.min(i, 8) * 78}ms`,
      });
      node.appendChild(el('i', { class: 'fin-award__hatch', aria: { hidden: 'true' } }));
      node.appendChild(el('div', { class: 'fin-award__title', text: award.title }));
      node.appendChild(el('div', { class: 'fin-award__crit', text: award.criterion }));

      if (award.holder) {
        node.appendChild(
          el(
            'div',
            { class: 'fin-award__who' },
            commanderTile(award.holder.name, award.holder.hue, award.holder.bot),
            el(
              'div',
              { class: 'fin-award__whoid' },
              el('span', { class: 'fin-award__whoname', text: award.holder.name }),
              el('span', {
                class: 'fin-award__whotag mono',
                style: `color:${cssHex(award.holder.color)}`,
                text: `[${award.holder.tag}]${award.holder.bot ? ' · AUTO' : ''}`,
              }),
            ),
          ),
        );
        node.appendChild(
          el(
            'div',
            { class: 'fin-award__value' },
            tallyNode(8, award.value, 'fin-award__v', TALLY_FAST_MS, (n) =>
              award.unit === 'M-EQ' || award.unit === 'UNIT PP' || award.unit === 'M-EQ IDLE'
                ? fmtNum(n)
                : String(Math.round(n)),
            ),
            el('i', { text: award.unit }),
          ),
        );
      } else {
        node.appendChild(
          el('div', { class: 'fin-award__blank', text: award.blank ?? 'NO DATA ON RECORD' }),
        );
      }

      node.appendChild(el('div', { class: 'fin-award__note', text: award.note }));
      awardWrap.appendChild(node);
    });

    if (awards.length === 0) {
      awardWrap.appendChild(
        el('div', { class: 'fin-board__none', text: 'NOTHING WORTH COMMENDING ON RECORD' }),
      );
    }

    stage.appendChild(
      block(
        8,
        'SEASON AWARDS',
        'FROM THE FINAL STATE',
        awardWrap,
        el('div', {
          class: 'fin-note',
          text: 'Every award above is computed from the world as it stood at the bell. Nothing is remembered that the game did not actually record.',
        }),
      ),
    );

    // ── 9: the way onward ───────────────────────────────────────────────────
    const outro = el('div', { class: 'fin-outro' });

    outro.appendChild(
      el('div', {
        class: 'fin-outro__line',
        text: iWon
          ? 'Eight weeks of holding ground, and the board closed with your banner on it. Nothing carries over but the record.'
          : myGuild
            ? `${myGuild.name} finished ${myRank >= 0 ? `#${myRank + 1}` : 'unranked'} of ${standings.length}. Territory was always time-limited — the rotation was going to take it either way. The war was the point.`
            : 'You ended the season unaffiliated. Every system in this war is guild-first; the next one will go better with a banner behind you.',
      }),
    );

    const restartHint =
      backend.kind === 'mock'
        ? 'hold — reseeds the offline sandbox with a brand-new world'
        : 'hold — reconnects the console to command';

    outro.appendChild(
      holdButton('OPEN THE NEXT SEASON', {
        variant: 'primary',
        holdMs: 1200,
        hint: restartHint,
        onComplete: () => {
          haptic([30, 50, 30, 50, 110]);
          window.location.reload();
        },
      }),
    );

    outro.appendChild(
      button('REPLAY THE CEREMONY', {
        variant: 'ghost',
        wide: true,
        icon: ICONS.refresh,
        onClick: () => {
          void play();
        },
      }),
    );

    outro.appendChild(
      el('p', {
        class: 'fin-outro__truth',
        text:
          backend.kind === 'mock'
            ? 'There is no season-reset call on the backend seam, so this restarts the client rather than pretending to wipe the world. The offline sandbox seeds a fresh world and a fresh season on every load, so a restart genuinely is a new season.'
            : 'There is no season-reset call on the backend seam, so this restarts the client rather than pretending to wipe the world. Against a live server you will land back on this screen until Command opens the next season.',
      }),
    );

    outro.appendChild(
      el('div', {
        class: 'fin-outro__sig mono',
        text: `${season.name} · ${standings.length} BANNERS · ${fmtNum(totalTiles)} TILES · CLOSED ${fmtClock(state.now)}`,
      }),
    );

    stage.appendChild(block(9, 'WHAT HAPPENS NOW', undefined, outro));

    composed = true;
  }

  // ── the sequence ──────────────────────────────────────────────────────────

  function landAllBeats(): void {
    for (let i = 1; i <= BEATS.length; i++) root.classList.add(`is-b${i}`);
    root.classList.remove('is-playing');
    root.classList.add('is-landed');
  }

  function clearBeats(): void {
    for (let i = 1; i <= BEATS.length; i++) root.classList.remove(`is-b${i}`);
    root.classList.remove('is-landed');
  }

  function runHooks(beat: number, s: Sequencer): void {
    for (const fn of hooks.get(beat) ?? []) fn(s);
  }

  function endCinematic(): void {
    root.classList.remove('is-playing');
    root.classList.add('is-landed');
    if (view.get().cinematic === 'season_end') view.patch({ cinematic: undefined });
  }

  function skip(): void {
    const active = seq;
    if (!active || active.finished) return;
    haptic(12);
    active.finish();
    for (let i = 1; i <= BEATS.length; i++) runHooks(i, active);
    landAllBeats();
    endCinematic();
  }

  async function play(): Promise<void> {
    seq?.dispose();
    const active = new Sequencer();
    seq = active;
    clearBeats();
    stage.scrollTop = 0;

    if (reducedMotion()) {
      active.finish();
      for (let i = 1; i <= BEATS.length; i++) runHooks(i, active);
      landAllBeats();
      if (view.get().cinematic === 'season_end') view.patch({ cinematic: undefined });
      return;
    }

    root.classList.add('is-playing');
    view.patch({ cinematic: 'season_end' });

    for (let i = 0; i < BEATS.length; i++) {
      if (seq !== active || active.finished) return;
      const beat = i + 1;
      root.classList.add(`is-b${beat}`);
      runHooks(beat, active);

      if (beat === 2) haptic([22, 46, 22]);
      if (beat === 3) {
        haptic([40, 60, 40, 60, 130]);
        flash.classList.remove('is-on');
        void flash.offsetWidth;
        flash.classList.add('is-on');
      }
      if (beat === 4) haptic([16, 34, 16]);
      if (beat === 5 || beat === 6 || beat === 8) haptic(10);

      await active.wait(BEATS[i]);
    }

    if (seq !== active) return;
    endCinematic();
  }

  // ── screen contract ───────────────────────────────────────────────────────

  tap.addEventListener('click', () => skip());

  const onScroll = (): void => {
    cue.classList.toggle('is-gone', stage.scrollTop > 40);
  };

  return {
    el: root,

    mount(): void {
      let started = false;

      const capture = (state: GameState | null): void => {
        if (!state || finalState) return;
        if (state.season.phase !== 'ended') return;
        // Freeze here: the world keeps simulating, the ceremony must not.
        finalState = state;
        compose(state);
        started = true;
        void play();
      };

      disposer.add(game.subscribe((state) => capture(state)));
      disposer.listen(stage, 'scroll', onScroll, { passive: true });
      capture(game.get());
      if (started) return;

      if (composed) {
        // Remounted after a detour: replay rather than dropping the reader into
        // a screen whose reveal already happened.
        void play();
        return;
      }

      clear(stage);
      stage.appendChild(
        el('div', {
          class: 'fin-board__none',
          text: 'AWAITING THE FINAL TALLY FROM COMMAND…',
        }),
      );
    },

    unmount(): void {
      disposer.dispose();
      seq?.dispose();
      seq = null;
      flash.classList.remove('is-on');
      if (view.get().cinematic === 'season_end') view.patch({ cinematic: undefined });
    },
  };
}
